content.content:
            response = run_claude([self.executable, "agents", "--json"], capture_output=True, text=True, timeout=15,
                                  retry_output=lambda result: listed_rows(result) is None)
        except subprocess.TimeoutExpired as error:
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: {error}") from error
        rows = listed_rows(response)
        if rows is None:
            # Claude Code is unavailable, which says nothing about any session.
            answer = f"exited {response.returncode}" if response.returncode else "printed no session list"
            detail = ((response.stderr or "").strip() or (response.stdout or "").strip())[-300:]
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: "
                                      f"`claude agents --json` {answer}" + (f": {detail}" if detail else ""))
        return rows

    def launch_name(self, node: str) -> str:
        """`workflow-<run>-<lane>`, `workflow-<run>-reviewer` for the default reviewer, `workflow-<run>-reviewer-<id>` otherwise."""
        if node == REVIEW:
            return f"workflow-{self.plan['run_id']}-reviewer"
        if node.startswith("review-"):
            return f"workflow-{self.plan['run_id']}-reviewer-{node[len('review-'):]}"
        return f"workflow-{self.plan['run_id']}-{node}"

    def node_worktree(self, node: str) -> Path:
        """Workers live in the plan's worktrees; every reviewer in the run's shared candidate checkout."""
        if is_review_node(node):
            return self.directory / "review-worktree"
        return Path(self.plan["nodes"][node]["worktree"])

    def locate(self, node: str, rows: list[dict]) -> dict | None:
        path = self.directory / f"{node}.interactive.json"
        if not path.exists():
            return None
        receipt = read_json(path)
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; cannot reconcile session")
        background_id = receipt.get("background_id")
        if not background_id:
            log = self.directory / f"{node}.launch.log"
            if not log.exists():
                return None
            # --bg assigns its own UUID. Bind the ID printed by this launch;
            # never adopt a guessed UUID or a name-only match.
            ids = set(re.findall(r"claude attach ([a-f0-9-]{8,36})\s", log.read_text(errors="replace")))
            if len(ids) != 1:
                raise RuntimeError("Missing/ambiguous native launch ID; reconcile manually")
            background_id = ids.pop()
        matches = [row for row in rows if row.get("id") == background_id]
        if not matches:
            return None
        if len(matches) != 1:
            raise RuntimeError("Ambiguous Claude session identity")
        row = matches[0]
        if row.get("kind") != "background" or Path(row.get("cwd", "")).resolve() != self.node_worktree(node).resolve() or row.get("name") != self.launch_name(node):
            raise RuntimeError("Claude session identity/worktree mismatch")
        if receipt.get("background_id") and row.get("sessionId") != receipt.get("session_id"):
            raise RuntimeError("Native Claude UUID changed; refusing attachment")
        if not isinstance(row.get("sessionId"), str) or not re.fullmatch(r"[a-f0-9-]{36}", row["sessionId"]):
            raise RuntimeError("Missing native Claude UUID")
        # `done` is a finished TURN, not a terminated terminal. Require the
        # native live PID as well; stale registry rows must not imply restart.
        if row.get("state") not in {"idle", "working", "blocked", "done"}:
            raise RuntimeError(f"Session is not attachable: {row.get('state')!r}; reconcile manually")
        pid = row.get("pid")
        if not isinstance(pid, int) or pid <= 0:
            raise RuntimeError("No live native PID; reconcile session before attaching")
        try:
            os.kill(pid, 0)
        except OSError as error:
            raise RuntimeError("Native process is unavailable; refusing implicit restart") from error
        return row

    settle_seconds = 30.0

    def settle(self, node: str) -> dict:
        """Bind the row created by the launch we just issued.

        `claude --bg` exits before the native session has fully registered: the
        inventory row can appear without a PID for a moment. Poll for the exact
        row until it is attachable; identity mismatches still fail immediately
        and nothing is ever launched again from here.
        """
        deadline = time.monotonic() + self.settle_seconds
        while True:
            try:
                row = self.locate(node, self.inventory())
            except RuntimeError as error:
                if "No live native PID" not in str(error) or time.monotonic() >= deadline:
                    raise
                row = None
            if row is not None:
                return row
            if time.monotonic() >= deadline:
                raise RuntimeError("No exact matching background session after launch")
            time.sleep(1)

    def reconcile(self, node: str, path: Path, receipt: dict) -> dict:
        """An existing receipt binds the one session this intent produced; nothing is launched again."""
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; refusing session reuse")
        row = self.locate(node, self.inventory())
        if row is None:
            raise RuntimeError("Existing launch cannot be reconciled; no automatic relaunch")
        receipt.update(status="attached_session_available", background_id=row["id"], session_id=row["sessionId"], observed_state=row["state"], native_started_at=row.get("startedAt"))
        receipt.pop("error", None)
        save_json(path, receipt)
        return receipt

    def launch(self, node: str, path: Path, receipt: dict, command: list[str], cwd: Path) -> dict:
        """Run the short `claude --bg` helper once, then bind the exact row it created."""
        env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
        try:
            # This command creates Claude's own persistent terminal, then exits.
            # Killing this short helper is NOT evidence that the session stopped.
            with (self.directory / f"{node}.launch.log").open("w") as log:
                try:
                    # Only an exec that failed (nothing ran) is repeated; a helper that ran is never run twice.
                    result = run_claude(command, cwd=cwd, env=env, stdout=log,
                                        stderr=subprocess.STDOUT, text=True, timeout=self.timeout)
                finally:
                    log.flush()
                    os.fsync(log.fileno())
            if result.returncode != 0:
                raise RuntimeError(f"Claude background launch exited {result.returncode}; inspect launch log")
            row = self.settle(node)
            receipt.update(status="attached_session_available", background_id=row["id"], session_id=row["sessionId"], observed_state=row["state"], native_started_at=row.get("startedAt"))
        except BaseException as error:
            receipt.update(status="needs_reconciliation", error=str(error))
            raise
        finally:
            save_json(path, receipt)
        return receipt

    def run(self, node: str) -> dict:
        if node not in self.workers or self.plan.get("mode") != "interactive":
            raise ValueError("Expected an interactive worker plan")
        info = self.plan["nodes"][node]
        path = self.directory / f"{node}.interactive.json"
        if path.exists():
            return self.reconcile(node, path, read_json(path))
        cwd = Path(info["worktree"])
        if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"] or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Worktree changed since preparation")
        # Native IDs do not exist until launch. Reject conflicting terminal names.
        if any(row.get("name") == self.launch_name(node) for row in self.inventory()):
            raise RuntimeError("Unowned session already exists with this launch name")
        receipt = {"node_id": node, "session_id": None, "launch_token": info["session_id"], "plan_digest": plan_digest(self.plan),
                   "worktree": str(cwd), "base_commit": self.plan["base_commit"],
                   "status": "launching", "attempt": 1, "launcher_invocations": 1,
                   "launch_requested_at": datetime.now(timezone.utc).isoformat()}
        save_json(path, receipt)
        automatic = bool(self.plan.get("automatic"))
        if automatic:
            from .automatic import validate_automatic
            validate_automatic(self.plan)
        tools = "Read,Glob,Grep,Edit,Write" if self.plan["allow_edits"] else "Read,Glob,Grep"
        if automatic:
            tools += ",Bash"
        prompt = worker_prompt(self.directory, self.plan, node)
        # The exact prompt is run evidence (the viewer shows it); it is private like the receipts.
        write_private(self.directory / f"{node}.prompt.txt", prompt)
        command = [self.executable, "--bg", "--name", self.launch_name(node), *background_settings(),
                   "--safe-mode", "--strict-mcp-config", "--mcp-config", '{"mcpServers":{}}',
                   "--tools", tools, "--permission-mode", "bypassPermissions" if automatic else "manual"]
        if automatic:
            command.append("--dangerously-skip-permissions")
        command.append(prompt)
        return self.launch(node, path, receipt, command, cwd)

    def run_reviewer(self, reviewer_id: str, prompt: str, launch_token: str, candidate_commit: str) -> dict:
        """Launch (or reconcile) one native reviewer session for this candidate.

        Every reviewer reads the same candidate checkout and the run directory; its only
        permitted write is its own completion file, which the controller later validates.
        """
        if self.plan.get("mode") != "interactive":
            raise ValueError("Expected an interactive run plan")
        node = review_node(reviewer_id)
        path = self.directory / f"{node}.interactive.json"
        if path.exists():
            return self.reconcile(node, path, read_json(path))
        cwd = self.node_worktree(node)
        if not cwd.is_dir():
            raise RuntimeError("Review worktree is missing; the review node creates it before launching a reviewer")
        if git(cwd, "rev-parse", "HEAD") != candidate_commit or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Review worktree is not at the clean candidate commit")
        if any(row.get("name") == self.launch_name(node) for row in self.inventory()):
            raise RuntimeError("Unowned session already exists with this launch name")
        receipt = {"node_id": node, "session_id": None, "launch_token": launch_token, "plan_digest": plan_digest(self.plan),
                   "worktree": str(cwd), "base_commit": self.plan["base_commit"], "candidate_commit": candidate_commit,
                   "status": "launching", "attempt": 1, "launcher_invocations": 1,
                   "launch_requested_at": datetime.now(timezone.utc).isoformat()}
        save_json(path, receipt)
        write_private(self.directory / f"{node}.prompt.txt", prompt)
        # Claude permission rules spell absolute paths as //absolute/path, and file writes are
        # governed by the Edit rule family (Write, Edit, NotebookEdit): under dontAsk a rule
        # spelled Write(...) never matches and every write is denied (seen live), while
        # Edit(//<path>) allows exactly that file and keeps every other write denied.
        completion = str(self.directory / f"{node}.completion.json").lstrip("/")
        # --tools, --allowedTools and --add-dir are variadic: any of them directly before the
        # positional prompt would swallow it (the session would start idle, without a task).
        # The prompt therefore follows --permission-mode, which takes exactly one value.
        command = [self.executable, "--bg", "--name", self.launch_name(node), *background_settings(),
                   "--safe-mode", "--strict-mcp-config", "--mcp-config", '{"mcpServers":{}}',
                   "--tools", "Read,Glob,Grep,Write", "--allowedTools", f"Edit(//{completion})",
                   "--add-dir", str(self.directory), "--permission-mode", "dontAsk", prompt]
        return self.launch(node, path, receipt, command, cwd)


def worker_prompt(directory: Path, plan: dict, node: str) -> str:
    """What a native worker session receives: the rules, its pinned task, the run's decisions.md, and in automatic mode the completion protocol."""
    prompt = ("You are a workflow worker in your own worktree. A human can type directly into this terminal. "
              "Do not launch agents, commit, merge, push or modify shared contracts. Stay within this worktree. "
              "Report changed files, checks actually executed, and open assumptions. "
              "Completion of a turn is not workflow approval.\n\n" + plan["nodes"][node]["task"] + decisions_block(plan))
    if plan.get("automatic"):
        from .automatic import completion_prompt
        prompt += completion_prompt(directory, plan, node)
    return prompt


def write_private(path: Path, text: str) -> None:
    path.write_text(text)
    os.chmod(path, 0o600)


def require_shell(pane_id: str, settle_seconds: float = 10.0) -> None:
    """Only type into a pane whose sole foreground process is its own idle shell.

    A pane Herdr just created reports no shell, or a shell still running its
    startup files, for a moment. Poll briefly for the idle-shell state; a pane
    that is still occupied at the deadline is refused, never typed into.
    """
    deadline = time.monotonic() + settle_seconds
    while True:
        process = herdr("pane", "process-info", "--pane", pane_id)["result"]["process_info"]
        foreground = process.get("foreground_processes", [])
        shell_pid = process.get("shell_pid")
        if shell_pid and len(foreground) == 1 and foreground[0].get("pid") == shell_pid:
            return
        if time.monotonic() >= deadline:
            raise RuntimeError(f"Pane {pane_id} is occupied; refusing to type an attach command into it")
        time.sleep(0.5)

        raise
    self.event(REVIEW, "interactive", f"Reviewer {reviewer_id} session {receipt['session_id']} launched; awaiting {node}.completion.json")
    if (self.directory / "terminals.json").exists() and os.environ.get("HERDR_ENV") == "1":
        # The pane is a convenience for the operator; its absence never fails the review. The
        # session is launched by now, so a Ctrl-C here is recorded, then propagated as an
        # interruption (the review node keeps the running session), never as a launch failure.
        try:
            attach_reviewer_panel(self.sessions)
            self.event(REVIEW, "running", f"Reviewer {reviewer_id} pane attached")
        except BaseException as error:
            self.event(REVIEW, "running", f"Reviewer {reviewer_id} pane not attached: {str(error) or type(error).__name__}")
            if not isinstance(error, Exception):
                raise
    return receipt

def reconcile_reviewer(self, reviewer_id: str = DEFAULT_REVIEWER) -> dict:
    """Bind the session an interrupted reviewer launch produced; nothing is launched."""
    node = review_node(reviewer_id)
    path = self.directory / f"{node}.interactive.json"
    if not path.exists():
        raise RuntimeError(f"No durable launch intent for reviewer {reviewer_id}; cannot reconcile without potentially launching a new reviewer")
    self.event(REVIEW, "running", f"Reconciling the interrupted launch of reviewer {reviewer_id}; nothing is relaunched")
    try:
        receipt = self.sessions.reconcile(node, path, read_json(path))
    except Exception as error:
        self.event(REVIEW, "blocked", f"Reviewer {reviewer_id}: {error}")
        raise
    self.event(REVIEW, "interactive", f"Reviewer {reviewer_id} session {receipt['session_id']} reconciled; awaiting {node}.completion.json")
    return receipt

def stop_session(self, node: str) -> None:
    """Persist native identity before stopping. Never signal guessed/reused PIDs."""
    marker = self.directory / f"{node}.stop.json"
    if marker.exists():
        intent = read_json(marker)
    else:
        row = self.sessions.locate(node, self.sessions.inventory())
        if row is None:
            raise RuntimeError(f"{node} session missing before stop; reconcile before continuing")
        intent = {"background_id": row["id"], "session_id": row["sessionId"], "pid": row["pid"], "stopped": False}
        save_json(marker, intent)
    if not intent["stopped"]:
        rows = self.sessions.inventory()
        matching = [row for row in rows if row.get("sessionId") == intent["session_id"] and row.get("pid")]
        if matching:
            row = self.sessions.locate(node, rows)
            if row is None or row["id"] != intent["background_id"] or row["pid"] != intent["pid"]:
                raise RuntimeError(f"Native {node} session identity changed after stop intent; reconcile manually")
            result = run_claude([self.sessions.executable, "stop", intent["background_id"]], capture_output=True, text=True, timeout=20)
            if result.returncode != 0:
                raise RuntimeError(f"Stop failed for {node}; inspect native session before retrying")
        # Recover stop-before-receipt without issuing another stop command.
        rows = self.sessions.inventory()
        if any(row.get("sessionId") == intent["session_id"] and row.get("pid") for row in rows) or pid_alive(intent["pid"]):
            raise RuntimeError(f"{node} termination is not established; retry after reconciliation")
        intent["stopped"] = True
        save_json(marker, intent)

def stop_workers(self):
    for node in self.workers:
        self.stop_session(node)
    stopped_ids = {read_json(self.directory / f"{node}.stop.json")["session_id"] for node in self.workers}
    if any(row.get("sessionId") in stopped_ids and row.get("pid") for row in self.sessions.inventory()):
        raise RuntimeError("A stopped worker was restarted; reconcile before snapshot capture")
    self.event("freeze", "stopped", f"Native workers stopped before snapshot capture: {', '.join(self.workers)}")

def stop_reviewer(self, reviewer_id: str = DEFAULT_REVIEWER):
    self.stop_session(review_node(reviewer_id))
    self.event(REVIEW, "stopped", f"Reviewer {reviewer_id} session stopped; its transcript stays resumable")

def check_ownership(self, node: str, changed: list[str]) -> None:
    """Every changed path is an exact repository path the lane owns: at freeze, and in a lane repair's snapshot."""
    # Ownership is enforced from the full declared policy: an excluded lane's paths are off-limits to every selected lane.
    excluded_paths = [(other, safe_path(prefix)) for other in self.excluded for prefix in self.worker_policy(other)["owned_paths"]]
    worker = self.worker_policy(node)
    for name in changed:
        safe_path(name)
        for other, prefix in excluded_paths:
            if owns(name, prefix):
                raise ValueError(f"Ownership violation: {node} edited {name}, owned by excluded lane {other}")
        if not any(owns(name, safe_path(prefix)) for prefix in worker["owned_paths"]):
            raise ValueError(f"{node} edited unowned path: {name}")

def freeze(self) -> dict:
    record = self.directory / "snapshots.json"
    if record.exists():
        return read_json(record)
    handoffs = {}
    for node in self.workers:
        handoff_path = self.directory / f"{node}.handoff.json"
        if not handoff_path.exists():
            raise ValueError(f"Missing {node} handoff: summary and open_assumptions are required")
        handoff = read_json(handoff_path)
        if set(handoff) != {"summary", "open_assumptions"} or not isinstance(handoff["summary"], str) or not handoff["summary"].strip() or not isinstance(handoff["open_assumptions"], list) or any(not isinstance(item, str) for item in handoff["open_assumptions"]):
            raise ValueError("Malformed worker handoff")
        handoffs[node] = handoff
    self.stop_workers()
    snapshots = {}
    for node in self.workers:
        cwd = Path(self.plan["nodes"][node]["worktree"])
        if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"]:
            raise ValueError("Worker changed HEAD; reconcile commits rather than silently accepting them")
        changed = changed_files(cwd, self.plan["base_commit"])
        self.check_ownership(node, changed)
        for name in changed:
            if (cwd / name).is_symlink():
                raise ValueError("Symlink changes require manual review before snapshot")
        index = self.directory / f"{node}.snapshot-index"
        if index.exists():
            index.unlink()  # Only our private temporary index, never a user's index.
        env = commit_env()
        env["GIT_INDEX_FILE"] = str(index)
        subprocess.run(["git", "-C", str(cwd), "read-tree", self.plan["base_commit"]], env=env, check=True)
        subprocess.run(["git", "-C", str(cwd), "add", "-A", "--", "."], env=env, check=True)
        tree = subprocess.check_output(["git", "-C", str(cwd), "write-tree"], env=env, text=True).strip()
        # Validate paths from the actual captured tree, including staged renames/deletes.
        captured = git(cwd, "diff-tree", "--no-commit-id", "--no-renames", "--name-only", "-r", self.plan["base_commit"], tree).splitlines()
        if sorted(captured) != changed:
            raise ValueError("Files changed during snapshot; refuse inconsistent evidence")
        commit = self.plan["base_commit"]
        if changed:
            commit = subprocess.check_output(["git", "-C", str(cwd), "-c", "commit.gpgsign=false", "commit-tree", tree,
                                              "-p", self.plan["base_commit"], "-m", f"Workflow {self.plan['run_id']}: {node}"], env=env, text=True).strip()
        ref = f"refs/workflow/{hashlib.sha256(str(self.directory).encode()).hexdigest()[:16]}/{node}"
        subprocess.run(["git", "-C", str(cwd), "update-ref", ref, commit], check=True)
        receipt = read_json(self.directory / f"{node}.interactive.json")
        snapshots[node] = {"commit": commit, "changed_files": changed, "session_id": receipt["session_id"], **handoffs[node]}
    save_json(record, snapshots)
    self.event("freeze", "succeeded", "Immutable snapshots captured; worker-reported checks are not trusted")
    return snapshots

def attempt(self, phase: str, node: str) -> int:
    """The lane's current attempt: from the floor of its revision (1, or the one a lane repair set) to the run's limit past it."""
    from .repair import attempt_floor
    path = self.directory / "attempts.json"
    value = read_json(path).get(f"{phase}:{node}", 1) if path.exists() else 1
    floor = attempt_floor(self.directory, phase, node)
    if type(value) is not int or value < floor or value >= floor + self.policy.get("max_verification_attempts", 3):
        raise ValueError("Verification attempt exceeds the run's hard limit")
    return value

def save_challenge(directory: Path, record: dict) -> None:
    """Validate, keep the record it replaces as `challenge-<attempt>.json`, then write the new one."""
    validate_schema("challenge", record)
    previous = load_challenge(directory)
    if previous is not None and previous.get("attempt"):
        archive = directory / f"challenge-{previous['attempt']}.json"
        if not archive.exists():  # The attempt as it was first decided (an accepted override keeps the paused record).
            save_json(archive, previous)
    save_json(challenge_path(directory), record)


def challenge_timeout(plan: dict) -> int:
    automatic = plan.get("automatic")
    return automatic["review_timeout_seconds"] if isinstance(automatic, dict) else DEFAULT_CHALLENGE_TIMEOUT


def challenge_worktree(runtime) -> Path:
    """A detached checkout at the base commit; the job gets only Read, Glob and Grep, and a change to it refuses the result."""
    cwd = runtime.directory / "challenge-worktree"
    base = runtime.plan["base_commit"]
    if not cwd.exists():
        git_worktree(runtime.plan["repository"], "add", "--detach", str(cwd), base)
    if git(cwd, "rev-parse", "HEAD") != base or git(cwd, "status", "--porcelain"):
        raise RuntimeError("Challenge worktree is not the clean base commit; reconcile before rerunning the challenge")
    return cwd


def run_challenge(runtime, attempt: int) -> dict:
    """One print job, validated and decided: `passed` without a P0/P1 concern, `paused` with one. No worker is launched here."""
    from .automatic import print_command
    directory, plan = runtime.directory, runtime.plan
    try:
        cwd = challenge_worktree(runtime)
    except BaseException as error:  # No job ran; the node must not keep a re-pin's `running` as its last status.
        runtime.event(CHALLENGE, "blocked", str(error) or type(error).__name__)
        raise
    session_id = str(uuid.uuid4())
    running = directory / "challenge.running.json"
    save_json(running, {"attempt": attempt, "session_id": session_id, "started_at": now()})
    prompt_path = directory / f"challenge-{attempt}.prompt.txt"
    prompt_path.write_text(challenge_prompt(directory, plan))
    os.chmod(prompt_path, 0o600)
    add_dirs = [str(directory / "challenge-inputs")] if plan.get("prd") else []
    command = print_command(runtime.sessions.executable, session_id, output_schema(), add_dirs)
    runtime.event(CHALLENGE, "running", f"Design challenge attempt {attempt}: one print job, session {session_id}")
    env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
    stdout = directory / f"challenge-{attempt}.stdout.json"
    try:
        with prompt_path.open() as stdin, stdout.open("w") as output, (directory / f"challenge-{attempt}.stderr.log").open("w") as errors:
            process = popen_claude(command, cwd=cwd, env=env, stdin=stdin, stdout=output, stderr=errors, text=True, start_new_session=True)
        try:
            process.wait(timeout=challenge_timeout(plan))
        except subprocess.TimeoutExpired:
            terminate(process)
            raise RuntimeError(f"Design challenge attempt {attempt} deadline exhausted; no worker was launched") from None
        except BaseException:
            terminate(process)
            raise
        try:
            result = read_json(stdout)
        except ValueError:
            result = {}
        if not isinstance(result, dict):  # A JSON array or string is no result either.
            result = {}
        if process.returncode != 0 or result.get("session_id") != session_id or result.get("is_error") is not False or result.get("subtype") != "success":
            raise RuntimeError(f"Design challenge attempt {attempt} did not succeed; inspect {stdout}. No worker was launched.")
        output = result.get("structured_output")
        try:
            validate_output(output)
        except Exception as error:
            raise RuntimeError(f"Design challenge attempt {attempt} output violates {CHALLENGE_SCHEMA.name}: {getattr(error, 'message', error)}") from None
        if git(cwd, "rev-parse", "HEAD") != plan["base_commit"] or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Challenge worktree changed during the job; refusing its result")
    except BaseException as error:
        runtime.event(CHALLENGE, "blocked", str(error) or type(error).__name__)
        raise
    blocking = [concern for concern in output["concerns"] if concern["severity"] in BLOCKING]
    record = {"version": "1.0.0", "run_id": plan["run_id"], "status": "paused" if blocking else "passed", "attempt": attempt,
              "session_id": session_id, "pinned": pinned_digests(directory, plan), "concerns": output["concerns"],
